;------------------------------------------------------------------------------
; 4000H - ROM module header of the CE-1600P printer / plotter ROM (bank 4)
; Module entries at +02H..+15H, then the fixed printer entries PCHEK, POUT,
; PKOUT and PCLEANUP (TRM: CALL Bank 4, 4020H/4023H/4026H/4029H).
;------------------------------------------------------------------------------
MODID4:
	defb 43H,16H                    ; 4000  4316
B4RESET:
	jp B4RESETFN                    ; 4002  c3277f       module +02H: reset / power functions
B4INTHOOK:
	jp B4INTFN                      ; 4005  c38c7c       module +05H: interrupt hook (EXROMCAL L = 05H from the bank-3 dispatcher)
B4PIOCS:
	jp PIOCSDISP                    ; 4008  c36850       module +08H: printer IOCS (C = 00H..31H)
	defb 00H,00H,00H                ; 400B  000000
B4AUTORUN:
	ld a,66H                        ; 400E  3e66         module +0EH
	ret                             ; 4010  c9
MODTAB4:
	defw 4030H                      ; 4011  3040
	defw B4TOKTAB                   ; 4013  a340
B4FILE:
	jp PBADFN                       ; 4015  c36150       module +15H: file handler
L4018:
	ret                             ; 4018  c9
L4019:
	ret                             ; 4019  c9
L401A:
	ret                             ; 401A  c9
L401B:
	ret                             ; 401B  c9
L401C:
	ret                             ; 401C  c9
L401D:
	ret                             ; 401D  c9
PRET:
	ret                             ; 401E  c9           printer IOCS 10H, 23H..27H: nothing (RET)
L401F:
	ret                             ; 401F  c9
PCHEK:
	jp PCHEK_I                      ; 4020  c3ae6f       is the printer ready?
POUT:
	jp POUT_I                       ; 4023  c3636f       print character E
PKOUT:
	jp PKOUT_I                      ; 4026  c3a56f       print character E (kana)
PCLEANUP:
	jp ALLOFF                       ; 4029  c3e056       mandatory post-processing after any printer IOCS
L402C:
	jp B4ENTRY2C                    ; 402C  c3e17f       fixed entry +2CH
B4DEVTAB:
	defb 02H,4CH,50H,54H,31H,00H,00H,00H; 402F               02H, then the device name "LPT1"



